132	/**
133	 * A SandboxManager implementation for Linux that uses Bubblewrap (bwrap).
134	 */
135	
136	export class LinuxSandboxManager implements SandboxManager {
137	  private static maskFilePath: string | undefined;
138	  private readonly denialCache: SandboxDenialCache = createSandboxDenialCache();
139	
140	  constructor(private readonly options: GlobalSandboxOptions) {}
141	
142	  isKnownSafeCommand(args: string[]): boolean {
143	    return isKnownSafeCommand(args);
144	  }
145	
146	  isDangerousCommand(args: string[]): boolean {
147	    return isDangerousCommand(args);
148	  }
149	
150	  parseDenials(result: ShellExecutionResult): ParsedSandboxDenial | undefined {
151	    return parsePosixSandboxDenials(result, this.denialCache);
152	  }
153	
154	  getWorkspace(): string {
155	    return this.options.workspace;
156	  }
157	
158	  getOptions(): GlobalSandboxOptions {
159	    return this.options;
160	  }
161	
162	  private getMaskFilePath(): string {
163	    if (
164	      LinuxSandboxManager.maskFilePath &&
165	      fs.existsSync(LinuxSandboxManager.maskFilePath)
166	    ) {
167	      return LinuxSandboxManager.maskFilePath;
168	    }
169	    const tempDir = fs.mkdtempSync(join(os.tmpdir(), 'gemini-cli-mask-file-'));
170	    const maskPath = join(tempDir, 'mask');
171	    fs.writeFileSync(maskPath, '');
172	    fs.chmodSync(maskPath, 0);
173	    LinuxSandboxManager.maskFilePath = maskPath;
174	
175	    // Cleanup on exit
176	    process.on('exit', () => {
177	      try {
178	        fs.rmSync(tempDir, { recursive: true, force: true });
179	      } catch {
180	        // Ignore errors
181	      }
182	    });
183	
184	    return maskPath;
185	  }
186	
187	  async prepareCommand(req: SandboxRequest): Promise<SandboxedCommand> {
188	    const isReadonlyMode = this.options.modeConfig?.readonly ?? true;
189	    const allowOverrides = this.options.modeConfig?.allowOverrides ?? true;
190	
191	    verifySandboxOverrides(allowOverrides, req.policy);
192	
193	    let command = req.command;
194	    let args = req.args;
195	
196	    // Translate virtual commands for sandboxed file system access
197	    if (command === '__read') {
198	      command = 'cat';
199	    } else if (command === '__write') {
200	      command = 'sh';
201	      args = ['-c', 'cat > "$1"', '_', ...args];
202	    }
203	
204	    const commandName = await getCommandName({ ...req, command, args });
205	    const isApproved = allowOverrides
206	      ? await isStrictlyApproved(
207	          { ...req, command, args },
208	          this.options.modeConfig?.approvedTools,
209	        )
210	      : false;
211	    const isYolo = this.options.modeConfig?.yolo ?? false;
212	    const workspaceWrite = !isReadonlyMode || isApproved || isYolo;
213	
214	    const networkAccess =
215	      this.options.modeConfig?.network || req.policy?.networkAccess || isYolo;
216	
217	    const persistentPermissions = allowOverrides
218	      ? this.options.policyManager?.getCommandPermissions(commandName)
219	      : undefined;
220	
221	    const mergedAdditional: SandboxPermissions = {
222	      fileSystem: {
223	        read: [
224	          ...(persistentPermissions?.fileSystem?.read ?? []),
225	          ...(req.policy?.additionalPermissions?.fileSystem?.read ?? []),
226	        ],
227	        write: [
228	          ...(persistentPermissions?.fileSystem?.write ?? []),
229	          ...(req.policy?.additionalPermissions?.fileSystem?.write ?? []),
230	        ],
231	      },
232	      network:
233	        networkAccess ||
234	        persistentPermissions?.network ||
235	        req.policy?.additionalPermissions?.network ||
236	        false,
237	    };
238	
239	    const { command: finalCommand, args: finalArgs } = handleReadWriteCommands(
240	      req,
241	      mergedAdditional,
242	      this.options.workspace,
243	      req.policy?.allowedPaths,
244	    );
