148	/**
149	 * Interface for a service that prepares commands for sandboxed execution.
150	 */
151	export interface SandboxManager {
152	  /**
153	   * Prepares a command to run in a sandbox, including environment sanitization.
154	   */
155	  prepareCommand(req: SandboxRequest): Promise<SandboxedCommand>;
