167	  /**
168	   * Parses the output of a command to detect sandbox denials.
169	   */
170	  parseDenials(result: ShellExecutionResult): ParsedSandboxDenial | undefined;
171	
172	  /**
173	   * Returns the primary workspace directory for this sandbox.
174	   */
