13	/**
14	 * Validates if the requested paths are within the allowed workspace or allowed paths.
15	 */
16	function validatePaths(
17	  paths: string[],
18	  workspace: string,
19	  allowedPaths: string[],
20	): boolean {
21	  for (const p of paths) {
22	    if (!isValidPathString(p)) {
23	      return false; // Reject malicious paths
24	    }
25	    const resolvedPath = path.resolve(p);
26	    const resolvedWorkspace = path.resolve(workspace);
27	    const isInsideWorkspace =
28	      resolvedPath.startsWith(resolvedWorkspace + path.sep) ||
29	      resolvedPath === resolvedWorkspace;
30	
31	    let isInsideAllowed = false;
32	    for (const allowed of allowedPaths) {
33	      const resolvedAllowed = path.resolve(allowed);
34	      if (
35	        resolvedPath.startsWith(resolvedAllowed + path.sep) ||
36	        resolvedPath === resolvedAllowed
37	      ) {
38	        isInsideAllowed = true;
39	        break;
40	      }
41	    }
42	
43	    if (!isInsideWorkspace && !isInsideAllowed) {
44	      return false; // Path traversal or unauthorized access attempt
45	    }
46	  }
47	  return true;
48	}
49	
50	export function handleReadWriteCommands(
51	  req: SandboxRequest,
52	  mergedAdditional: SandboxPermissions,
53	  workspace: string,
54	  allowedPaths: string[] = [],
55	): { command: string; args: string[] } {
56	  let finalCommand = req.command;
57	  let finalArgs = req.args;
58	
59	  if (req.command === '__read') {
60	    finalCommand = '/bin/cat';
61	    if (req.args.length > 0) {
62	      if (validatePaths(req.args, workspace, allowedPaths)) {
63	        mergedAdditional.fileSystem!.read!.push(...req.args);
64	      } else {
65	        throw new Error(
66	          `Sandbox Error: Path traversal or unauthorized access attempt detected in __read: ${req.args.join(', ')}`,
67	        );
68	      }
69	    }
70	  } else if (req.command === '__write') {
71	    finalCommand = '/bin/sh';
72	    finalArgs = ['-c', 'tee -- "$@" > /dev/null', '_', ...req.args];
73	    if (req.args.length > 0) {
74	      if (validatePaths(req.args, workspace, allowedPaths)) {
75	        mergedAdditional.fileSystem!.write!.push(...req.args);
76	      } else {
77	        throw new Error(
78	          `Sandbox Error: Path traversal or unauthorized access attempt detected in __write: ${req.args.join(', ')}`,
79	        );
80	      }
81	    }
82	  }
83	
84	  return { command: finalCommand, args: finalArgs };
85	}
