31	export function resolveGitWorktreePaths(workspacePath: string): {
32	  worktreeGitDir?: string;
33	  mainGitDir?: string;
34	} {
35	  try {
36	    const gitPath = path.join(workspacePath, '.git');
37	    const gitStat = fs.lstatSync(gitPath);
38	    if (gitStat.isFile()) {
39	      const gitContent = fs.readFileSync(gitPath, 'utf8');
40	      const match = gitContent.match(/^gitdir:\s+(.+)$/m);
41	      if (match && match[1]) {
42	        let worktreeGitDir = match[1].trim();
43	        if (!path.isAbsolute(worktreeGitDir)) {
44	          worktreeGitDir = path.resolve(workspacePath, worktreeGitDir);
45	        }
46	        const resolvedWorktreeGitDir = tryRealpath(worktreeGitDir);
47	
48	        // Security check: Verify the bidirectional link to prevent sandbox escape
49	        let isValid = false;
50	        try {
51	          const backlinkPath = path.join(resolvedWorktreeGitDir, 'gitdir');
52	          const backlink = fs.readFileSync(backlinkPath, 'utf8').trim();
53	          // The backlink must resolve to the workspace's .git file
54	          if (tryRealpath(backlink) === tryRealpath(gitPath)) {
55	            isValid = true;
56	          }
57	        } catch {
58	          // Fallback for submodules: check core.worktree in config
59	          try {
60	            const configPath = path.join(resolvedWorktreeGitDir, 'config');
61	            const config = fs.readFileSync(configPath, 'utf8');
62	            const match = config.match(/^\s*worktree\s*=\s*(.+)$/m);
63	            if (match && match[1]) {
64	              const worktreePath = path.resolve(
65	                resolvedWorktreeGitDir,
66	                match[1].trim(),
67	              );
68	              if (tryRealpath(worktreePath) === tryRealpath(workspacePath)) {
69	                isValid = true;
70	              }
71	            }
72	          } catch {
73	            // Ignore
74	          }
75	        }
76	
77	        if (!isValid) {
78	          return {}; // Reject: valid worktrees/submodules must have a readable backlink
79	        }
80	
81	        const mainGitDir = tryRealpath(
82	          path.dirname(path.dirname(resolvedWorktreeGitDir)),
83	        );
84	        return {
85	          worktreeGitDir: resolvedWorktreeGitDir,
86	          mainGitDir: mainGitDir.endsWith('.git') ? mainGitDir : undefined,
87	        };
88	      }
89	    }
90	  } catch {
91	    // Ignore if .git doesn't exist, isn't readable, etc.
92	  }
93	  return {};
94	}
