11	  type SandboxManager,
12	  type SandboxRequest,
13	  type SandboxedCommand,
14	  type SandboxPermissions,
15	  type GlobalSandboxOptions,
16	  type ParsedSandboxDenial,
17	  resolveSandboxPaths,
18	} from '../../services/sandboxManager.js';
