20	import {
21	  sanitizeEnvironment,
22	  getSecureSanitizationConfig,
23	} from '../../services/environmentSanitization.js';
24	import { buildSeatbeltProfile } from './seatbeltArgsBuilder.js';
25	import { initializeShellParsers } from '../../utils/shell-utils.js';
26	import {
27	  isKnownSafeCommand,
28	  isDangerousCommand,
29	} from '../utils/commandSafety.js';
30	import {
31	  verifySandboxOverrides,
32	  getCommandName as getFullCommandName,
33	  isStrictlyApproved,
34	} from '../utils/commandUtils.js';
