36	  parsePosixSandboxDenials,
37	  createSandboxDenialCache,
38	  type SandboxDenialCache,
39	} from '../utils/sandboxDenialUtils.js';
40	import { handleReadWriteCommands } from '../utils/sandboxReadWriteUtils.js';
41	
42	export class MacOsSandboxManager implements SandboxManager {
43	  private readonly denialCache: SandboxDenialCache = createSandboxDenialCache();
44	
45	  constructor(private readonly options: GlobalSandboxOptions) {}
46	
47	  isKnownSafeCommand(args: string[]): boolean {
48	    const toolName = args[0];
49	    const approvedTools = this.options.modeConfig?.approvedTools ?? [];
50	    if (toolName && approvedTools.includes(toolName)) {
51	      return true;
52	    }
53	    return isKnownSafeCommand(args);
54	  }
55	
56	  isDangerousCommand(args: string[]): boolean {
57	    return isDangerousCommand(args);
58	  }
59	
60	  parseDenials(result: ShellExecutionResult): ParsedSandboxDenial | undefined {
61	    return parsePosixSandboxDenials(result, this.denialCache);
62	  }
63	
64	  getWorkspace(): string {
65	    return this.options.workspace;
66	  }
67	
68	  getOptions(): GlobalSandboxOptions {
69	    return this.options;
70	  }
71	
72	  async prepareCommand(req: SandboxRequest): Promise<SandboxedCommand> {
73	    await initializeShellParsers();
74	    const sanitizationConfig = getSecureSanitizationConfig(
75	      req.policy?.sanitizationConfig,
76	    );
77	
78	    const sanitizedEnv = sanitizeEnvironment(req.env, sanitizationConfig);
79	
80	    const isReadonlyMode = this.options.modeConfig?.readonly ?? true;
81	    const allowOverrides = this.options.modeConfig?.allowOverrides ?? true;
82	
83	    // Reject override attempts in plan mode
84	    verifySandboxOverrides(allowOverrides, req.policy);
85	
86	    let command = req.command;
87	    let args = req.args;
88	
89	    // Translate virtual commands for sandboxed file system access
90	    if (command === '__read') {
91	      command = '/bin/cat';
92	    } else if (command === '__write') {
93	      command = '/bin/sh';
94	      args = ['-c', 'cat > "$1"', '_', ...args];
95	    }
96	
97	    const currentReq = { ...req, command, args };
98	
99	    // If not in readonly mode OR it's a strictly approved pipeline, allow workspace writes
100	    const isApproved = allowOverrides
101	      ? await isStrictlyApproved(
102	          currentReq,
103	          this.options.modeConfig?.approvedTools,
104	        )
105	      : false;
106	
107	    const isYolo = this.options.modeConfig?.yolo ?? false;
108	    const workspaceWrite = !isReadonlyMode || isApproved || isYolo;
109	    const defaultNetwork =
110	      this.options.modeConfig?.network || req.policy?.networkAccess || isYolo;
111	
112	    // Fetch persistent approvals for this command
113	    const commandName = await getFullCommandName(currentReq);
114	    const persistentPermissions = allowOverrides
115	      ? this.options.policyManager?.getCommandPermissions(commandName)
116	      : undefined;
117	
118	    const mergedAdditional: SandboxPermissions = {
119	      fileSystem: {
120	        read: [
121	          ...(persistentPermissions?.fileSystem?.read ?? []),
122	          ...(req.policy?.additionalPermissions?.fileSystem?.read ?? []),
123	        ],
124	        write: [
125	          ...(persistentPermissions?.fileSystem?.write ?? []),
126	          ...(req.policy?.additionalPermissions?.fileSystem?.write ?? []),
127	        ],
128	      },
129	      network:
130	        defaultNetwork ||
131	        persistentPermissions?.network ||
132	        req.policy?.additionalPermissions?.network ||
133	        false,
134	    };
135	
136	    const { command: finalCommand, args: finalArgs } = handleReadWriteCommands(
137	      req,
138	      mergedAdditional,
139	      this.options.workspace,
140	      [
141	        ...(req.policy?.allowedPaths || []),
142	        ...(this.options.includeDirectories || []),
143	      ],
144	    );
145	
146	    const resolvedPaths = await resolveSandboxPaths(
147	      this.options,
148	      req,
149	      mergedAdditional,
150	    );
151	
152	    const sandboxArgs = buildSeatbeltProfile({
153	      resolvedPaths,
154	      networkAccess: mergedAdditional.network,
155	      workspaceWrite,
156	    });
157	
158	    const tempFile = this.writeProfileToTempFile(sandboxArgs);
159	
160	    return {
161	      program: '/usr/bin/sandbox-exec',
162	      args: ['-f', tempFile, '--', finalCommand, ...finalArgs],
163	      env: sanitizedEnv,
164	      cwd: req.cwd,
165	      cleanup: () => {
166	        try {
167	          fs.unlinkSync(tempFile);
168	        } catch {
169	          // Ignore cleanup errors
170	        }
171	      },
172	    };
173	  }
174	
175	  private writeProfileToTempFile(profile: string): string {
176	    const tempFile = path.join(
177	      os.tmpdir(),
178	      `gemini-cli-seatbelt-${Date.now()}-${Math.random().toString(36).slice(2)}.sb`,
179	    );
180	    fs.writeFileSync(tempFile, profile, { mode: 0o600 });
181	    return tempFile;
182	  }
