/**
 * Builds the list of bubblewrap arguments based on the provided options.
 */
export async function buildBwrapArgs(
  options: BwrapArgsOptions,
): Promise<string[]> {
  const { resolvedPaths } = options;
  const workspaceOriginal = resolvedPaths.workspace.original;
  const workspaceResolved = resolvedPaths.workspace.resolved;

  const bwrapArgs: string[] = [
    '--unshare-all',
    '--new-session', // Isolate session
    '--die-with-parent', // Prevent orphaned runaway processes
  ];

  if (options.networkAccess) {
    bwrapArgs.push('--share-net');
  }

  bwrapArgs.push(
    '--ro-bind',
    '/',
    '/',
    '--dev', // Creates a safe, minimal /dev (replaces --dev-bind)
    '/dev',
    '--proc', // Creates a fresh procfs for the unshared PID namespace
    '/proc',
    '--tmpfs', // Provides an isolated, writable /tmp directory
    '/tmp',
  );

  const bindFlag = options.workspaceWrite ? '--bind-try' : '--ro-bind-try';

  // Bind the workspace directory using its original (pre-resolution) path.
  bwrapArgs.push(bindFlag, workspaceOriginal, workspaceOriginal);

  // Auto-detect and support git worktrees by binding the underlying git dir.
  const { worktreeGitDir, mainGitDir } =
    resolveGitWorktreePaths(workspaceResolved);
  if (worktreeGitDir) {
    bwrapArgs.push(bindFlag, worktreeGitDir, worktreeGitDir);
  }
  if (mainGitDir) {
    bwrapArgs.push(bindFlag, mainGitDir, mainGitDir);
  }

  // Grant write access to paths explicitly permitted for writing and to paths
  // allowed by the command policy. All other paths remain read-only via the
  // top-level `--ro-bind / /` mount.
  const bindAllowed = (path: string) => {
    if (!fs.existsSync(path)) {
      // If the path doesn't exist, we still want to allow access to its parent
      // if it's explicitly allowed, to enable creating it.
      try {
        const resolvedParent = tryRealpath(dirname(path));
        bwrapArgs.push(
          options.isWriteCommand ? '--bind-try' : bindFlag,
          resolvedParent,
          resolvedParent,
        );
      } catch {
        // Ignore
      }
      return;
    }
    bwrapArgs.push('--bind-try', path, path);
  };

  for (const path of resolvedPaths.policyWrite) {
    bindAllowed(path);
  }
  for (const path of resolvedPaths.policyAllowed) {
    bindAllowed(path);
  }

  // Protect governance files. Locate them relative to the resolved workspace,
  // and also bind the original-path variant when it differs.
  for (const file of GOVERNANCE_FILES) {
    const originalFilePath = join(workspaceOriginal, file.path);
    bwrapArgs.push('--ro-bind', originalFilePath, originalFilePath);

    const resolvedFilePath = join(workspaceResolved, file.path);
    if (resolvedFilePath !== originalFilePath) {
      bwrapArgs.push('--ro-bind', resolvedFilePath, resolvedFilePath);
    }
