      if (isErrnoException(e) && e.code === 'ENOENT') {
        bwrapArgs.push('--symlink', '/dev/null', forbiddenPath);
      } else {
        debugLogger.warn(
          `Failed to stat forbidden path ${forbiddenPath}: ${e instanceof Error ? e.message : String(e)}`,
